              "label": "steady ground target",
              "before": "const fs=require('fs'),path=require('path'),test=require('node:test'),assert=require('node:assert/strict'),ts=require(process.env.MAPILLARY_TYPESCRIPT||'typescript');\nfunction load(file,req=()=>{}){const m={exports:{}};new Function('require','module','exports',ts.transpileModule(fs.readFileSync(path.join(__dirname,'../src/i18n',file),'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}).outputText)(req,m,m.exports);return m.exports}\nconst {en}=load('messages.ts'),tr=load('locales/tr.ts').default,{message,languageOf,preferenceOf}=load('core.ts',()=>({en}));\ntest('Turkish has all English keys with exactly matching placeholders',()=>{assert.deepEqual(Object.keys(tr).sort(),Object.keys(en).sort());const placeholders=s=>[...s.matchAll(/\\{([a-zA-Z][a-zA-Z0-9]*)\\}/g)].map(x=>x[1]).sort();for(const key of Object.keys(en)){assert.equal(typeof tr[key],'string');assert(tr[key].trim().length>0,key);assert.deepEqual(placeholders(tr[key]),placeholders(en[key]),key)}});\ntest('locale normalization and stored preference accept only supported choices',()=>{for(const locale of['tr','tr-TR','TR_tr'])assert.equal(languageOf(locale),'tr');for(const locale of[undefined,'en-US','ar','trailing','de-DE'])assert.equal(languageOf(locale),'en');assert.equal(preferenceOf('tr'),'tr');assert.equal(preferenceOf('en'),'en');for(const value of['auto','de','',null])assert.equal(preferenceOf(value),'auto')});\ntest('fallback and full-message substitution retain zero and literal user text',()=>{assert.equal(message({},'timeTravel'),'Time travel');assert.equal(message(tr,'captureOption',{date:'31 Eki 2026',distance:0}),'31 Eki 2026 \u00b7 0 m uzakta');assert.equal(message(en,'iconSize',{label:'<script>x</script>'}),'<script>x</script> icon size');assert.equal(message(en,'iconSize'),'{label} icon size')});\ntest('builder language policy controls defaults and optional viewer overrides',()=>{const{requestedLanguage}=load('core.ts',()=>({en}));assert.equal(requestedLanguage('tr-TR','auto','auto',true),'tr');assert.equal(requestedLanguage('tr-TR','en','auto',true),'en');assert.equal(requestedLanguage('en-US','tr','en',true),'en');assert.equal(requestedLanguage('en-US','tr','en',false),'tr');assert.equal(requestedLanguage('en-US','en','tr',false),'en');assert.equal(requestedLanguage('de-DE','auto','auto',false),'en')});\ntest('builder Turkish covers every setting message without changing service/config values',()=>{const{settingsEn}=load('settingsMessages.ts'),settingsTr=load('locales/settings-tr.ts').default;assert.deepEqual(Object.keys(settingsTr).sort(),Object.keys(settingsEn).sort());for(const key of Object.keys(settingsEn)){assert(settingsTr[key].trim(),key);assert.deepEqual([...settingsTr[key].matchAll(/\\{([^}]+)\\}/g)].map(x=>x[1]),[...settingsEn[key].matchAll(/\\{([^}]+)\\}/g)].map(x=>x[1]),key)}assert.equal(settingsTr.defaultWidgetLanguage,'Varsay\u0131lan bile\u015fen dili');assert.equal(settingsTr.customArcgisRouteService,'\u00d6zel ArcGIS rota servisi')});\n",
